{
  "decisions": [
    {
      "requirement_id": "MED-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by executing the application to create a record and observing that all specified fields are captured."
    },
    {
      "requirement_id": "MED-002",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The distinct colors for the four triage categories are verified by running the application and visually observing the UI elements."
    },
    {
      "requirement_id": "MED-003",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by inputting valid and invalid vital sign values to observe correct recording and rejection behavior."
    },
    {
      "requirement_id": "MED-004",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by disabling network connectivity and creating 500 records to ensure the application remains functional and stores them locally."
    },
    {
      "requirement_id": "MED-005",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by simulating conflicting edits, restoring connectivity, and observing the synchronization and conflict resolution behavior."
    },
    {
      "requirement_id": "MED-006",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The use of AES-256 encryption is verified by inspecting the code or configuration to confirm the correct algorithm is implemented."
    },
    {
      "requirement_id": "MED-007",
      "methods": [
        "Gösterim"
      ],
      "rationale": "The operability with surgical gloves is verified by a user wearing gloves interacting with the interface to demonstrate usability."
    },
    {
      "requirement_id": "MED-008",
      "methods": [
        "Test"
      ],
      "rationale": "The battery life requirement is verified by running the application under the defined usage profile and measuring the duration until battery depletion."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "AI-001",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by submitting documents and observing that the system returns exactly one category and a confidence score within the specified range."
    },
    {
      "requirement_id": "AI-002",
      "methods": [
        "Analiz"
      ],
      "rationale": "Achieving a specific macro-averaged F1 score requires statistical evaluation and calculation on a held-out dataset."
    },
    {
      "requirement_id": "AI-003",
      "methods": [
        "Test"
      ],
      "rationale": "The routing behavior is verified by submitting documents with low confidence scores and observing that they are directed to the human review queue."
    },
    {
      "requirement_id": "AI-004",
      "methods": [
        "Test"
      ],
      "rationale": "Performance under load is verified by executing the service with 50 requests per second and measuring the response times to check the 95th percentile."
    },
    {
      "requirement_id": "AI-005",
      "methods": [
        "İnceleme"
      ],
      "rationale": "The logging requirement is verified by inspecting the recorded logs or database entries to ensure the model version, input hash, and predicted category are present."
    },
    {
      "requirement_id": "AI-006",
      "methods": [
        "Analiz"
      ],
      "rationale": "Detecting distribution deviation requires calculating the population stability index and comparing it against the threshold, which is a statistical analysis task."
    },
    {
      "requirement_id": "AI-007",
      "methods": [
        "Test"
      ],
      "rationale": "The functionality is verified by submitting a document and observing that the response includes the three specified text passages."
    },
    {
      "requirement_id": "AI-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Comparing recall metrics between different language groups requires statistical analysis of the model's performance on segmented datasets."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KK-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gecikme süresi, sistemin çalıştırılması ve sensör girdilerinin verilmesiyle ölçülerek doğrulanabilir."
    },
    {
      "requirement_id": "KK-002",
      "methods": [
        "Test"
      ],
      "rationale": "Yük testi ile 2.000 iz altında ekran yenileme hızının 10 Hz'in üzerinde kalıp kalmadığı gözlemlenebilir."
    },
    {
      "requirement_id": "KK-003",
      "methods": [
        "Gösterim"
      ],
      "rationale": "Operatörün seçtiği izin detaylarının ekranda doğru görüntülenip görüntülenmediği çalıştırılarak gözlemlenebilir."
    },
    {
      "requirement_id": "KK-004",
      "methods": [
        "Test"
      ],
      "rationale": "Zamanlayıcı mantığı, girdi akışının durdurulması ve zamanın izlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "KK-005",
      "methods": [
        "Test"
      ],
      "rationale": "Tanımlı bölgeye iz girdiğinde görsel ve sesli uyarıların tetiklenip tetiklenmediği çalıştırılarak doğrulanabilir."
    },
    {
      "requirement_id": "KK-006",
      "methods": [
        "Test"
      ],
      "rationale": "Mesaj iletim süresi ve durum bildirimi, mesaj gönderilerek ve zaman ölçülerek test edilebilir."
    },
    {
      "requirement_id": "KK-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Kayıt tutma mekanizmasının değiştirilemezlik özelliği ve log yapısı, kod veya yapılandırma incelemesiyle doğrulanabilir."
    },
    {
      "requirement_id": "KK-008",
      "methods": [
        "Test"
      ],
      "rationale": "Sunucu arızası senaryosu simüle edilerek devralma süresi ve veri bütünlüğü test edilebilir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": [
        "Test"
      ],
      "rationale": "Sistemin e-Devlet entegrasyonu ile oturum açma işlevinin çalışıp çalışmadığı, gerçek veya simüle edilmiş kimlik doğrulama girdileri verilerek gözlemlenmelidir."
    },
    {
      "requirement_id": "KMU-002",
      "methods": [
        "Test"
      ],
      "rationale": "15 dakikalık inaktivite süresinin sonunda oturumun sonlandırılması ve yönlendirme davranışının, zamanlayıcı testleri ile doğrulanması gerekir."
    },
    {
      "requirement_id": "KMU-003",
      "methods": [
        "Test"
      ],
      "rationale": "Art arda 5 başarısız giriş denemesi sonrası hesap kilitlenmesi ve 30 dakikalık kilit süresinin, senaryo tabanlı testler ile kontrol edilmelidir."
    },
    {
      "requirement_id": "KMU-004",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut limiti (10 MB) ve adet limiti (5 dosya) kısıtlarının, farklı girdi kombinasyonları ile sisteme yüklenerek test edilmesi gerekir."
    },
    {
      "requirement_id": "KMU-005",
      "methods": [
        "Test"
      ],
      "rationale": "Başvuru tamamlanınca benzersiz takip numarası üretimi ve e-posta ile bildirim gönderiminin, uçtan uca test senaryoları ile doğrulanması gerekir."
    },
    {
      "requirement_id": "KMU-006",
      "methods": [
        "Test"
      ],
      "rationale": "Taslak kaydetme işlevi ve 30 günlük süre içinde kaldığı yerden devam etme yeteneğinin, zaman ve veri tutarlılığı testleri ile doğrulanması gerekir."
    },
    {
      "requirement_id": "KMU-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "WCAG 2.1 AA uyumluluğunun, kullanıcı arayüzünün kod yapısı, HTML semantiği ve erişilebilirlik araçları ile gözle denetlenerek (inceleme) doğrulanması gerekir."
    },
    {
      "requirement_id": "KMU-008",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Verilerin yalnızca Türkiye sınırları içindeki sunucularda saklandığının, altyapı yapılandırma belgeleri ve sunucu konum ayarlarının gözle denetlenmesi (inceleme) ile doğrulanması gerekir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gereksinim, belirli bir girdi (geçersiz belirteç) verildiğinde sistemin gözlemlenebilir davranışını (HTTP 401 yanıtı) tanımladığı için test ile doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Rol tabanlı erişim kontrolünün ve yetkisiz isteklerde HTTP 403 yanıtının, farklı rollerle yapılan istekler üzerinden sistemin çalıştırılarak gözlemlenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "Hız sınırlama eşiğinin aşılması durumunda sistemin HTTP 429 yanıtı ve Retry-After başlığı döndürmesi, yük testi senaryoları ile gözlemlenerek doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Analiz"
      ],
      "rationale": "Belirli bir yük altında (2.000 istek/sn) 99. persentil gecikme metriklerinin istatistiksel olarak hesaplanması ve değerlendirilmesi gerektiği için analiz yöntemi uygundur."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "Arka uç servisin yanıt vermemesi durumunda zaman aşımının tetiklenmesi ve HTTP 504 yanıtının üretilmesi, simüle edilmiş gecikme senaryolarıyla test edilerek doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "Yeniden başlatma olmadan yapılandırma değişikliğinin uygulanması ve devam eden isteklerin düşmemesi, canlı sistem üzerinde yapılan dinamik testlerle gözlemlenmelidir."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "İsteklerin işlenmesinin ardından günlük dosyalarında beklenen alanların (izleme kimliği, süre vb.) doğru şekilde kaydedildiğinin kontrolü, sistem çalıştırılarak ve çıktı gözlemlenerek test ile doğrulanır."
    },
    {
      "requirement_id": "SW-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Aylık kullanılabilirlik yüzdesinin (99.95%) hesaplanması, uzun vadeli istatistiksel veri analizi ve metrik değerlendirmesi gerektirdiği için analiz yöntemi seçilir."
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Macro-averaged F1 score verification on held-out set",
      "covers": [
        "AI-002"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and the held-out evaluation dataset is available.",
      "test_inputs": "Held-out evaluation dataset containing documents from all defined classes.",
      "assumptions": "The evaluation script correctly computes the macro-averaged F1 score.",
      "steps": [
        {
          "no": 1,
          "action": "Run the evaluation pipeline on the held-out evaluation set.",
          "expected": "The system completes the classification and evaluation process without errors."
        },
        {
          "no": 2,
          "action": "Extract the calculated macro-averaged F1 score from the evaluation report.",
          "expected": "The reported macro-averaged F1 score is 0.90 or greater."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Recall parity between Turkish and English documents",
      "covers": [
        "AI-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and the held-out evaluation dataset contains labeled documents in both Turkish and English.",
      "test_inputs": "Held-out evaluation dataset split by language (Turkish and English subsets).",
      "assumptions": "The evaluation script can compute recall separately for the Turkish and English subsets of the data.",
      "steps": [
        {
          "no": 1,
          "action": "Run the evaluation pipeline on the held-out evaluation set, filtering results by document language.",
          "expected": "The system calculates the recall metric for Turkish documents and the recall metric for English documents."
        },
        {
          "no": 2,
          "action": "Calculate the absolute difference between the Turkish recall and the English recall.",
          "expected": "The absolute difference is less than or equal to 5 percentage points."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "WCAG 2.1 AA Uyumluluğunun Test Araçlarıyla Doğrulanması",
      "covers": [
        "KMU-007"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "E-Başvuru Portalı test ortamında yayımlanmıştır ve tarayıcı uyumluluk testleri için hazırdır.",
      "test_inputs": "Portalın ana sayfası ve temel başvuru formu URL'leri.",
      "assumptions": "Test ortamında Lighthouse, axe-core veya benzeri standart bir WCAG test aracı kullanılabilir.",
      "steps": [
        {
          "no": 1,
          "action": "Portalın ana sayfası ve başvuru formu sayfasında WCAG 2.1 AA uyumlu bir test aracı (örneğin Lighthouse veya axe-core) çalıştırılır.",
          "expected": "Test aracı, WCAG 2.1 AA kriterlerine uygunluk sağlandığını ve hata (error) seviyesinde ihlal bulunmadığını raporlar."
        },
        {
          "no": 2,
          "action": "Raporlanan 'warning' veya 'recommendation' seviyesindeki uyarılar incelenir.",
          "expected": "Uyarılar, WCAG 2.1 AA zorunlu kriterlerini ihlal etmemekte olup yalnızca iyileştirme önerileri niteliğindedir."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-SW-001-01",
      "title": "OAuth 2.0 erişim belirteci olmayan isteğin reddedilmesi",
      "covers": [
        "SW-001"
      ],
      "type": "Hata",
