{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "Casualty data encryption verification",
      "covers": [
        "MED-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is installed and operational on the tablet. A test casualty record has been created and saved.",
      "test_inputs": "A valid casualty record containing identifiable data (e.g., Name: 'TestPatient', ID: '12345').",
      "assumptions": "Access to the device file system or a hex dump tool is available to inspect the raw storage data.",
      "steps": [
        {
          "no": 1,
          "action": "Create a new casualty record with known plaintext data (e.g., 'TestPatient') and save it to the device.",
          "expected": "The application confirms the successful save of the casualty record."
        },
        {
          "no": 2,
          "action": "Locate the storage location for casualty data on the device file system and inspect the raw byte content corresponding to the saved record.",
          "expected": "The raw data does not contain the plaintext string 'TestPatient' or any other identifiable plain text from the record."
        },
        {
          "no": 3,
          "action": "Verify the cryptographic configuration or metadata associated with the storage volume or file to confirm the encryption standard used.",
          "expected": "The system configuration or file headers indicate that AES-256 encryption is applied to the casualty data."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "Battery life under defined usage profile",
      "covers": [
        "MED-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The tablet battery is fully charged (100%). The 'defined usage profile' is documented and available. The tablet is connected to a power source for initial charging only, then disconnected for the test.",
      "test_inputs": "A pre-defined script or manual procedure representing the 'defined usage profile' (e.g., continuous triage entry, screen on at 50% brightness, 4G/Wi-Fi active).",
      "assumptions": "The 'defined usage profile' is a standardized sequence of operations agreed upon by the project team. The test environment temperature is within normal operating limits.",
      "steps": [
        {
          "no": 1,
          "action": "Start the tablet with a full battery and begin executing the defined usage profile continuously.",
          "expected": "The application remains stable and responsive during the execution of the usage profile."
        },
        {
          "no": 2,
          "action": "Monitor the battery level and elapsed time until the battery reaches 0% or the device shuts down.",
          "expected": "The device continues to operate for a duration of at least 8 hours before the battery is depleted."
        }
      ]
    },
    {
      "id": "TC-03",
      "title": "Battery life boundary check at 8 hours",
      "covers": [
        "MED-008"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "The tablet battery is fully charged. The 'defined usage profile' is active.",
      "test_inputs": "Timer set to 8 hours.",
      "assumptions": "The usage profile is maintained consistently throughout the 8-hour period.",
      "steps": [
        {
          "no": 1,
          "action": "Execute the defined usage profile for exactly 8 hours.",
          "expected": "The device is still operational and the application is responsive at the 8-hour mark."
        },
        {
          "no": 2,
          "action": "Check the remaining battery percentage after 8 hours of usage.",
          "expected": "The battery level is greater than 0%, indicating the device can operate for at least the minimum required duration."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-MED-004-01",
      "title": "Offline functionality and local storage of 500 records",
      "covers": [
        "MED-004"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Application is installed on the tablet. Network connectivity is disabled (Airplane mode or no signal). Local storage is cleared or empty.",
      "test_inputs": "500 unique casualty record data sets.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Launch the application while network connectivity is disabled.",
          "expected": "The application opens and main functions are accessible without error messages regarding connectivity."
        },
        {
          "no": 2,
          "action": "Create a new casualty record with valid data.",
          "expected": "The record is saved successfully to local storage."
        },
        {
          "no": 3,
          "action": "Repeat the creation process until 500 casualty records are stored locally.",
          "expected": "All 500 records are saved successfully. The application remains responsive and functional."
        },
        {
          "no": 4,
          "action": "Verify the count of locally stored records in the application's data management view.",
          "expected": "The application displays a count of at least 500 records."
        },
        {
          "no": 5,
          "action": "Attempt to view and edit one of the existing records while offline.",
          "expected": "The record is displayed correctly and edits can be made and saved locally."
        }
      ]
    },
    {
      "id": "TC-MED-004-02",
      "title": "Local storage boundary for 500 records",
      "covers": [
        "MED-004"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "Application is offline. Local storage contains exactly 499 valid casualty records.",
      "test_inputs": "1 additional casualty record data set.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Create a new casualty record to reach the 500th record.",
          "expected": "The 500th record is saved successfully. The application remains fully functional."
        },
        {
          "no": 2,
          "action": "Verify the application's ability to list and access all 500 records.",
          "expected": "All 500 records are accessible and viewable without performance degradation or errors."
        }
      ]
    },
    {
      "id": "TC-MED-005-01",
      "title": "Synchronization of non-conflicting records upon connectivity restoration",
      "covers": [
        "MED-005"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Application is offline. Local storage contains new records not present on the server. Network connectivity is disabled.",
      "test_inputs": "Valid casualty records created locally.",
      "assumptions": "Server is accessible and contains no conflicting edits for the specific records being synced.",
      "steps": [
        {
          "no": 1,
          "action": "Enable network connectivity on the tablet.",
          "expected": "The application detects the connection and initiates synchronization."
        },
        {
          "no": 2,
          "action": "Wait for the synchronization process to complete.",
          "expected": "Local records are successfully transmitted to the server. The local database reflects the server state for these records (e.g., marked as synced)."
        },
        {
          "no": 3,
          "action": "Verify the records on the server side.",
          "expected": "The records created locally are present on the server with correct data."
        }
      ]
    },
    {
      "id": "TC-MED-005-02",
      "title": "Resolution of conflicting edits by keeping both versions",
      "covers": [
        "MED-005"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "Application is offline. A specific casualty record exists on both the server and the local device. The record has been modified on the server side after the last sync. The same record is then modified locally on the device.",
      "test_inputs": "Conflicting modifications to the same casualty record field (e.g., triage status).",
      "assumptions": "The conflict detection mechanism is active.",
      "steps": [
        {
